    st,_=call("POST",f"/api/session/{a}/prompt",{"id":"msg_cancel_right","text":"CLIENT-CANCEL-RIGHT","delivery":"queue"}); need(st==200,"queue admission failed")
    before=[r.get("id") for r in inbox(a)]
    ack=client.request_pending_deletion(a,"msg_cancel_right")
    after=[r.get("id") for r in inbox(a)]
    # Keep all synthetic provider calls held until wrong-session and interrupt checks finish.
    result["cases"]["correct_session_delete"]={"ack":ack,"queued_id_before": "msg_cancel_right" in before,"queued_id_after":"msg_cancel_right" in after}
    need(result["cases"]["correct_session_delete"]=={"ack":{"status":"acknowledged"},"queued_id_before":True,"queued_id_after":False},"correct-session deletion observation mismatch")
    # Wrong-session 204 control: B's ID passed with A's session. Method acknowledges, B remains.
    b=client.create_session("wrong-session-target",str(root/"work"),"mock/fake",DENY)
    client.submit_prompt(b,"msg_wrong_held","CLIENT-HELD")
    need(held.wait(1),"provider hold did not remain active for second fixture")
    st,_=call("POST",f"/api/session/{b}/prompt",{"id":"msg_foreign_delete","text":"CLIENT-FOREIGN-DELETE","delivery":"queue"}); need(st==200,"foreign queue admission failed")
    b_before=[r.get("id") for r in inbox(b)]
    wrong_ack=client.request_pending_deletion(a,"msg_foreign_delete")
    direct_wrong_status,_=call("DELETE",f"/api/session/{a}/inbox/msg_foreign_delete")
    b_after=[r.get("id") for r in inbox(b)]
    result["cases"]["wrong_session_delete"]={"module_ack":wrong_ack,"direct_route_status":direct_wrong_status,"target_id_present_before":"msg_foreign_delete" in b_before,"target_id_present_after":"msg_foreign_delete" in b_after,"wrong_session_inbox_count":len(inbox(a))}
    need(result["cases"]["wrong_session_delete"]["module_ack"]=={"status":"acknowledged"} and result["cases"]["wrong_session_delete"]["direct_route_status"]==204 and result["cases"]["wrong_session_delete"]["target_id_present_before"] and result["cases"]["wrong_session_delete"]["target_id_present_after"],"wrong-session negative control mismatch")
